using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK discovers tools by scanning for [McpServerToolType] on the class
/// and [McpServerTool] on each public method. Parameter attributes feed the LLM
/// with names, descriptions, and type info so it can call tools correctly.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    // HttpClient is injected by the DI container (see Program.cs).
    // The SDK resolves constructor/method parameters from IServiceProvider
    // the same way ASP.NET controllers do.
    private readonly HttpClient _http;

    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool(Name = "get_weather")]
    [Description("Get current weather for a location using latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url);

        if (response?.Current is null)
            return "Unable to fetch weather data.";

        var c = response.Current;
        return $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h";
    }

    [McpServerTool(Name = "get_forecast")]
    [Description("Get a 7-day daily temperature forecast for a location.")]
    public async Task<string> GetForecastAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&daily=temperature_2m_max,temperature_2m_min&forecast_days=7";

        var response = await _http.GetFromJsonAsync<ForecastResponse>(url);

        if (response?.Daily is null)
            return "Unable to fetch forecast data.";

        var lines = response.Daily.Time.Select((date, i) =>
            $"{date}: High {response.Daily.MaxTemp[i]}°C, Low {response.Daily.MinTemp[i]}°C");

        return string.Join('\n', lines);
    }
}

// --- JSON models for Open-Meteo API responses ---

public sealed class WeatherResponse
{
    [JsonPropertyName("current")]
    public CurrentWeather? Current { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; set; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; set; }
}

public sealed class ForecastResponse
{
    [JsonPropertyName("daily")]
    public DailyForecast? Daily { get; set; }
}

public sealed class DailyForecast
{
    [JsonPropertyName("time")]
    public string[] Time { get; set; } = [];

    [JsonPropertyName("temperature_2m_max")]
    public double[] MaxTemp { get; set; } = [];

    [JsonPropertyName("temperature_2m_min")]
    public double[] MinTemp { get; set; } = [];
}

